#include "stdlib/blas/ext/base/cfill_not_equal.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/reim.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/blas/base/shared.h"

/**
* Replaces single-precision complex floating-point strided array elements not equal to a provided search element with a specified scalar constant.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param alpha         scalar constant
* @param X             input array
* @param strideX       stride length
*/
void API_SUFFIX(stdlib_strided_cfill_not_equal)( const CBLAS_INT N, const stdlib_complex64_t searchElement, const stdlib_complex64_t alpha, stdlib_complex64_t *X, const CBLAS_INT strideX ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	API_SUFFIX(stdlib_strided_cfill_not_equal_ndarray)( N, searchElement, alpha, X, strideX, ox );
}

/**
* Replaces single-precision complex floating-point strided array elements not equal to a provided search element with a specified scalar constant using alternative indexing semantics.
*
* @param N             number of indexed elements
* @param searchElement search element
* @param alpha         scalar constant
* @param X             input array
* @param strideX       stride length
* @param offsetX       starting index
*/
void API_SUFFIX(stdlib_strided_cfill_not_equal_ndarray)( const CBLAS_INT N, const stdlib_complex64_t searchElement, const stdlib_complex64_t alpha, stdlib_complex64_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	CBLAS_INT ix;
	CBLAS_INT i;
	float sre;
	float sim;
	float re;
	float im;

	if ( N <= 0 ) {
		return;
	}

	// Decompose the search element into its real and imaginary components:
	stdlib_complex64_reim( searchElement, &sre, &sim );

	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		stdlib_complex64_reim( X[ ix ], &re, &im );
		if ( re != sre || im != sim ) {
			X[ ix ] = alpha;
		}
		ix += strideX;
	}
	return;
}
